CREATE TABLE IF NOT EXISTS admins (id INT PRIMARY KEY AUTO_INCREMENT,username VARCHAR(80) UNIQUE NOT NULL,password_hash VARCHAR(180) NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash CHAR(64) PRIMARY KEY,admin_id INT NOT NULL,expires_at DATETIME NOT NULL,FOREIGN KEY(admin_id) REFERENCES admins(id) ON DELETE CASCADE,INDEX(expires_at));
CREATE TABLE IF NOT EXISTS login_attempts (attempt_key CHAR(64) PRIMARY KEY,attempts INT NOT NULL,window_start DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS profile (id INT PRIMARY KEY,full_name VARCHAR(120) NOT NULL,headline VARCHAR(180) NOT NULL,bio TEXT NOT NULL,email VARCHAR(180) NOT NULL,location VARCHAR(120) NOT NULL,avatar_url VARCHAR(300) NOT NULL DEFAULT '',availability VARCHAR(180) NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS skills (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,category VARCHAR(100) NOT NULL,level INT NOT NULL DEFAULT 80,sort_order INT NOT NULL DEFAULT 0,CHECK(level BETWEEN 0 AND 100));
CREATE TABLE IF NOT EXISTS education (id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,organization VARCHAR(180) NOT NULL,period VARCHAR(100) NOT NULL,description TEXT NOT NULL,sort_order INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS experience LIKE education;
CREATE TABLE IF NOT EXISTS projects (id INT AUTO_INCREMENT PRIMARY KEY,slug VARCHAR(120) UNIQUE NOT NULL,title VARCHAR(180) NOT NULL,summary VARCHAR(500) NOT NULL,description TEXT NOT NULL,technologies VARCHAR(250) NOT NULL,image_url VARCHAR(300) NOT NULL DEFAULT '',github_url VARCHAR(300) NOT NULL DEFAULT '',demo_url VARCHAR(300) NOT NULL DEFAULT '',published BOOLEAN NOT NULL DEFAULT FALSE,sort_order INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS social_links (id INT AUTO_INCREMENT PRIMARY KEY,label VARCHAR(100) NOT NULL,url VARCHAR(300) NOT NULL,sort_order INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS media (id INT AUTO_INCREMENT PRIMARY KEY,filename VARCHAR(80) UNIQUE NOT NULL,mime VARCHAR(80) NOT NULL,size_bytes INT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS schema_migrations (version VARCHAR(40) PRIMARY KEY,applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
